<?php
declare(strict_types=1);
const ORIGIN='https://desertskytourism.com';
const STAGING=false;
require_once __DIR__.'/users.php';
define('PUBLIC_ROOT',dirname(__DIR__).'/public_html');
function esc($v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function respond($v,int $code=200):never{http_response_code($code);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode($v,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE);exit;}
function database():PDO{static $db;if($db)return $db;$dir=__DIR__.'/storage';if(!is_dir($dir))mkdir($dir,0700,true);$db=new PDO('sqlite:'.$dir.'/cms.sqlite');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec('PRAGMA busy_timeout=5000; PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS records(kind TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL,PRIMARY KEY(kind,id)); CREATE TABLE IF NOT EXISTS accounts(email TEXT PRIMARY KEY,hash TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1); CREATE TABLE IF NOT EXISTS limits(id TEXT PRIMARY KEY,started INTEGER,n INTEGER); CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY,created INTEGER);');@chmod($dir.'/cms.sqlite',0600);
 if(!getRecord('system','seeded')){foreach(json_decode(file_get_contents(__DIR__.'/seed.json'),true) as $kind=>$items)foreach($items as $item)putRecord($kind,$item['id'],$item);putRecord('system','seeded',['at'=>gmdate('c')]);}
 if(file_exists(__DIR__.'/initial-admin.json')){$a=json_decode(file_get_contents(__DIR__.'/initial-admin.json'),true);$q=$db->prepare('INSERT OR IGNORE INTO accounts(email,hash) VALUES(?,?)');$q->execute([strtolower($a['email']),password_hash($a['password'],PASSWORD_DEFAULT)]);unlink(__DIR__.'/initial-admin.json');}return $db;}
function sql(string $query,array $args=[]):PDOStatement{$q=database()->prepare($query);$q->execute($args);return $q;}
function secretStorageKey():string{$file=__DIR__.'/storage/secret.key';$handle=fopen($file,'c+b');if(!$handle)throw new RuntimeException('Private secret storage unavailable.');chmod($file,0600);flock($handle,LOCK_EX);rewind($handle);$key=stream_get_contents($handle);if($key===''){$key=random_bytes(32);rewind($handle);fwrite($handle,$key);fflush($handle);}flock($handle,LOCK_UN);fclose($handle);if(strlen($key)!==32)throw new RuntimeException('Invalid private encryption key.');return $key;}
function getRecord(string $kind,string $id):?array{$v=sql('SELECT data FROM records WHERE kind=? AND id=?',[$kind,$id])->fetchColumn();if(!$v)return null;$data=json_decode($v,true);if($kind==='secrets'&&!empty($data['__sealed'])){$plain=openssl_decrypt(base64_decode($data['cipher']),'aes-256-gcm',secretStorageKey(),OPENSSL_RAW_DATA,base64_decode($data['nonce']),base64_decode($data['tag']));if($plain===false)throw new RuntimeException('Unable to decrypt private configuration.');return json_decode($plain,true,64,JSON_THROW_ON_ERROR);}return $data;}
function putRecord(string $kind,string $id,array $data):void{$encoded=json_encode($data,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);if($kind==='secrets'){$nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($encoded,'aes-256-gcm',secretStorageKey(),OPENSSL_RAW_DATA,$nonce,$tag);if($cipher===false)throw new RuntimeException('Unable to save private configuration.');$encoded=json_encode(['__sealed'=>1,'nonce'=>base64_encode($nonce),'tag'=>base64_encode($tag),'cipher'=>base64_encode($cipher)],JSON_THROW_ON_ERROR);}sql('INSERT INTO records VALUES(?,?,?) ON CONFLICT(kind,id) DO UPDATE SET data=excluded.data',[$kind,$id,$encoded]);}
function records(string $kind,bool $all=false):array{$r=array_map(fn($s)=>json_decode($s,true),sql('SELECT data FROM records WHERE kind=?',[$kind])->fetchAll(PDO::FETCH_COLUMN));if($kind==='locations'){$order=['dubai'=>0,'abu-dhabi'=>1,'ras-al-khaimah'=>2];usort($r,fn($a,$b)=>($order[$a['id']]??100)<=>($order[$b['id']]??100));}return $all?$r:array_values(array_filter($r,fn($v)=>empty($v['deletedAt'])&&($v['status']??'published')==='published'&&(empty($v['publishedAt'])||substr($v['publishedAt'],0,10)<=gmdate('Y-m-d'))));}
function settings():array{return getRecord('settings','site')??[];}
function sessionOpen():void{if(session_status()!==PHP_SESSION_ACTIVE){session_name('dst_session');session_set_cookie_params(['secure'=>true,'httponly'=>true,'samesite'=>'Lax','path'=>'/','lifetime'=>0]);session_start();}if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));}
function isAdmin():bool{sessionOpen();if(empty($_SESSION['admin'])||($_SESSION['expires']??0)<time()||accountDisabled($_SESSION['admin']))return false;$a=sql('SELECT version FROM accounts WHERE email=?',[$_SESSION['admin']])->fetchColumn();return $a&&(int)$a===(int)($_SESSION['version']??0);}
function authorize():void{if(!isAdmin())respond(['error'=>'Please sign in to the dashboard.'],401);}
function sameOrigin():void{if(($_SERVER['HTTP_ORIGIN']??'')!==ORIGIN)respond(['error'=>'Invalid request origin.'],403);}
function csrf():void{sameOrigin();sessionOpen();if(!hash_equals($_SESSION['csrf'],$_SERVER['HTTP_X_CSRF_TOKEN']??''))respond(['error'=>'Refresh the page and try again.'],403);}
function throttle(string $name,int $max=20,int $window=300):void{$id=$name.':'.hash('sha256',$_SERVER['REMOTE_ADDR']??'');$d=database();$d->beginTransaction();$r=sql('SELECT started,n FROM limits WHERE id=?',[$id])->fetch(PDO::FETCH_ASSOC);$n=$r&&$r['started']>time()-$window?(int)$r['n']+1:1;$start=$n===1?time():(int)$r['started'];sql('INSERT OR REPLACE INTO limits VALUES(?,?,?)',[$id,$start,$n]);$d->commit();if($n>$max)respond(['error'=>'Too many attempts. Please try again later.'],429);}
function jsonInput():array{if((int)($_SERVER['CONTENT_LENGTH']??0)>1500000)respond(['error'=>'Request is too large.'],413);try{return json_decode(file_get_contents('php://input'),true,64,JSON_THROW_ON_ERROR);}catch(Throwable){respond(['error'=>'Invalid request.'],400);}}
function slugify(string $v):string{return trim(preg_replace('/[^a-z0-9]+/','-',strtolower($v)),'-');}
function text($v,int $max=2000):string{return mb_substr(trim(strip_tags((string)$v)),0,$max);}
function safeImage($v):string{$v=(string)$v;return !str_contains($v,'..')&&preg_match('~^/(assets|uploads)/[a-zA-Z0-9/_.-]+$~',$v)?$v:'/assets/dubai.webp';}
function cleanHTML($v):string{$v=preg_replace('~<(script|style|iframe|object|form|svg|noscript)\b[^>]*>[\s\S]*?</\1>~i','',(string)$v);return preg_replace_callback('~</?([a-z][a-z0-9]*)\b([^>]*)>~i',function($m){$n=strtolower($m[1]);if(!in_array($n,['p','h2','h3','h4','strong','b','em','i','ul','ol','li','a','br','blockquote','hr','table','tr','th','td']))return '';if(str_starts_with($m[0],'</'))return '</'.$n.'>';$attr='';if($n==='a'&&preg_match('~href\s*=\s*["\']([^"\']+)["\']~i',$m[2],$a)&&preg_match('~^(https://|/[^/]|mailto:|tel:|#)~',$a[1]))$attr=' href="'.esc($a[1]).'"';return '<'.$n.$attr.'>';},$v);}
function price(array $t):float{return (float)(isset($t['discountPrice'])&&$t['discountPrice']!==''?$t['discountPrice']:($t['price']??0));}
function money($v):string{return 'AED '.number_format((float)$v,((float)$v===(float)(int)$v)?0:2);}
function pathFor(array $p,string $kind='tours'):string{if(!empty($p['systemPath']))return $p['systemPath'];return '/'.($kind==='posts'?'guides/':($kind==='locations'?'destinations/':($kind==='pages'?'':'tours/'))).$p['slug'];}
function findSlug(string $kind,string $slug):?array{foreach(records($kind) as $p)if($p['slug']===$slug)return $p;return null;}
function locationName(string $id):string{return (getRecord('locations',$id)['title']??$id);}
function notFound():never{http_response_code(404);renderPage('Page not found','This page may have moved. Explore our latest experiences.','<section class="container section"><h1>A little off the beaten path.</h1><p>Let’s get you back to your next adventure.</p><a class="button" href="/tours">Explore tours</a></section>',[],true);exit;}
function smtpConfig():array{return getRecord('secrets','mail')??[];}
function notifyMail(string $to,string $subject,string $body):bool{$c=smtpConfig();if(empty($c['password'])||!filter_var($to,FILTER_VALIDATE_EMAIL))return false;require_once __DIR__.'/phpmailer/Exception.php';require_once __DIR__.'/phpmailer/PHPMailer.php';require_once __DIR__.'/phpmailer/SMTP.php';try{$m=new PHPMailer\PHPMailer\PHPMailer(true);$m->isSMTP();$m->Host=$c['host'];$m->SMTPAuth=true;$m->Username=$c['username'];$m->Password=$c['password'];$m->SMTPSecure=(int)$c['port']===465?'ssl':'tls';$m->Port=(int)$c['port'];$m->Timeout=15;$m->CharSet='UTF-8';$m->setFrom($c['username'],'Desert Sky Tourism');$m->addAddress($to);$m->addReplyTo(settings()['email']);$m->Subject=$subject;$m->Body=$body;$m->send();return true;}catch(Throwable){return false;}}
set_exception_handler(function(Throwable $e){error_log('Desert Sky: '.$e->getMessage());if(str_starts_with($_SERVER['REQUEST_URI']??'','/api/'))respond(['error'=>'We could not complete this request. Please try again.'],500);http_response_code(500);echo 'We are temporarily unable to load this page. Please try again shortly.';});
